"""Class 1 - Anatomy of an agent, built from scratch.

Scenario (clinical): a prior-authorization intake assistant receives a free-text question
from a clinic and must decide which tools to call before answering:
    "Does member M-2231 need prior auth for a lumbar MRI, and how fast will we hear back?"

We implement the same task two ways:
  1. a fixed WORKFLOW  - the developer hard-codes the steps
  2. an AGENT          - the model chooses the next tool each turn (ReAct loop)

Run:  python -m classes.class01_intro_agentic_ai.example
"""
from __future__ import annotations

import json

from common.llm import get_llm
from common.tools import ToolRegistry, tool

# --------------------------------------------------------------------------- tools (fake systems)
POLICIES = {
    "mri lumbar": {"policy_id": "MP-RAD-014", "requires_pa": True, "codes": ["72148"]},
    "semaglutide": {"policy_id": "MP-RX-221", "requires_pa": True, "codes": ["semaglutide"]},
    "office visit": {"policy_id": None, "requires_pa": False, "codes": ["99213"]},
}
MEMBERS = {"M-2231": {"plan": "Gold PPO", "active": True, "pa_turnaround_days": {"standard": 3, "urgent": 1}}}


@tool()
def find_policy(service: str) -> dict:
    """Look up whether a service requires prior authorization and which medical policy applies."""
    s = service.lower()
    for key, val in POLICIES.items():
        if all(w in s for w in key.split()):
            return {"service": key, **val}
    return {"service": service, "policy_id": None, "requires_pa": "unknown"}


@tool()
def check_member(member_id: str) -> dict:
    """Return plan and eligibility details for a health-plan member ID like M-1234."""
    m = MEMBERS.get(member_id)
    if not m:
        raise KeyError(f"member {member_id} not found")
    return {"member_id": member_id, **m}


@tool()
def turnaround(member_id: str, urgent: bool = False) -> dict:
    """Return the expected prior-auth decision time in days for a member (urgent or standard)."""
    days = MEMBERS[member_id]["pa_turnaround_days"]["urgent" if urgent else "standard"]
    return {"member_id": member_id, "urgent": urgent, "days": days}


registry = ToolRegistry().register(find_policy, check_member, turnaround)

QUESTION = "Does member M-2231 need prior auth for a lumbar MRI, and how fast will we hear back?"


# --------------------------------------------------------------------------- 1. workflow
def workflow(question: str) -> str:
    """Deterministic: always the same three calls in the same order."""
    policy = registry.call("find_policy", {"service": "MRI lumbar"}).output
    member = registry.call("check_member", {"member_id": "M-2231"}).output
    t = registry.call("turnaround", {"member_id": "M-2231"}).output
    return (f"Prior auth required: {policy['requires_pa']} (policy {policy['policy_id']}). "
            f"Member on {member['plan']}; expect a decision in {t['days']} business days.")


# --------------------------------------------------------------------------- 2. agent (ReAct)
SYSTEM = """You are a prior-authorization intake assistant for a health plan.
Use the tools to look up facts; never guess policy or eligibility.
When you have enough information, answer in two sentences and name the policy ID."""


def offline_planner(observations: list[dict]):
    """Stand-in for the model's reasoning when no API key is set.
    It mimics what a good model does: gather missing facts, then answer."""
    called = {o["tool"] for o in observations}
    if "find_policy" not in called:
        return lambda: {"tool": "find_policy", "args": {"service": "lumbar MRI"},
                        "thought": "I need to know if a lumbar MRI requires PA."}
    if "check_member" not in called:
        return lambda: {"tool": "check_member", "args": {"member_id": "M-2231"},
                        "thought": "Confirm the member is active and see their plan."}
    if "turnaround" not in called:
        return lambda: {"tool": "turnaround", "args": {"member_id": "M-2231", "urgent": False},
                        "thought": "The user asked how fast - get standard turnaround."}
    p = next(o["output"] for o in observations if o["tool"] == "find_policy")
    t = next(o["output"] for o in observations if o["tool"] == "turnaround")
    return lambda: {"final": f"Yes - a lumbar MRI requires prior authorization under {p['policy_id']}. "
                             f"For member M-2231 a standard decision takes about {t['days']} business days."}


def agent(question: str, max_steps: int = 6, verbose: bool = True) -> str:
    llm = get_llm()
    messages = [{"role": "system", "content": SYSTEM}, {"role": "user", "content": question}]
    observations: list[dict] = []
    for step in range(1, max_steps + 1):
        action = llm.next_action(messages, registry.schemas(), fallback=offline_planner(observations))
        if "final" in action:
            if verbose:
                print(f"  step {step}: FINAL -> {action['final']}")
            return action["final"]
        if verbose:
            print(f"  step {step}: {action.get('thought', '')}\n           ACT  {action['tool']}({action['args']})")
        res = registry.call(action["tool"], action["args"])
        obs = res.output if res.ok else {"error": res.error}
        if verbose:
            print(f"           OBS  {json.dumps(obs)}")
        observations.append({"tool": action["tool"], "output": obs})
        # feed the observation back (OpenAI tool-message format when online)
        call_id = action.get("call_id", f"call_{step}")
        messages.append({"role": "assistant", "content": None, "tool_calls": [
            {"id": call_id, "type": "function",
             "function": {"name": action["tool"], "arguments": json.dumps(action["args"])}}]})
        messages.append({"role": "tool", "tool_call_id": call_id, "content": json.dumps(obs)})
    return "Stopped: step budget exhausted (escalate to a human)."


if __name__ == "__main__":
    print(f"LLM mode: {get_llm().mode}\n")
    print("1) WORKFLOW (developer decides the steps)")
    print("  ", workflow(QUESTION))
    print("\n2) AGENT (model decides the steps - ReAct loop)")
    answer = agent(QUESTION)
    print("\nAudit trail (every tool call is logged):")
    for e in registry.audit:
        print(f"   {e['tool']:<12} ok={e['ok']}  {e['latency_ms']}ms")

"""Class 1 - The same ReAct agent expressed as a LangGraph state machine.

    START -> reason --(tool?)--> act -> reason ... --(final)--> END

Why a graph? The loop becomes explicit, inspectable state. You get checkpoints,
interrupts for human approval, streaming and retries for free - all used later in the course.

Run:  python -m classes.class01_intro_agentic_ai.langgraph_version
"""
from __future__ import annotations

import operator
from typing import Annotated, TypedDict

from langgraph.graph import END, START, StateGraph

from common.llm import get_llm

from .example import QUESTION, SYSTEM, offline_planner, registry


class AgentState(TypedDict):
    question: str
    observations: Annotated[list[dict], operator.add]   # reducer: append, never overwrite
    pending: dict | None
    answer: str | None
    steps: int


def reason(state: AgentState) -> dict:
    llm = get_llm()
    msgs = [{"role": "system", "content": SYSTEM}, {"role": "user", "content": state["question"]}]
    msgs += [{"role": "user", "content": f"Observation from {o['tool']}: {o['output']}"}
             for o in state["observations"]]
    action = llm.next_action(msgs, registry.schemas(), fallback=offline_planner(state["observations"]))
    if "final" in action:
        return {"answer": action["final"], "pending": None, "steps": state["steps"] + 1}
    return {"pending": action, "steps": state["steps"] + 1}


def act(state: AgentState) -> dict:
    a = state["pending"]
    res = registry.call(a["tool"], a["args"])
    return {"observations": [{"tool": a["tool"], "output": res.output if res.ok else {"error": res.error}}],
            "pending": None}


def route(state: AgentState) -> str:
    if state["answer"] or state["steps"] >= 6:
        return END
    return "act"


def build_graph():
    g = StateGraph(AgentState)
    g.add_node("reason", reason)
    g.add_node("act", act)
    g.add_edge(START, "reason")
    g.add_conditional_edges("reason", route, {"act": "act", END: END})
    g.add_edge("act", "reason")
    return g.compile()


if __name__ == "__main__":
    app = build_graph()
    print(app.get_graph().draw_mermaid())          # the diagram in the README is generated from this
    for event in app.stream({"question": QUESTION, "observations": [], "pending": None,
                             "answer": None, "steps": 0}, stream_mode="updates"):
        for node, update in event.items():
            print(f"[{node}] {update}")

"""Class 6 - An MCP server that exposes the AIOps tools, runbooks and a prompt.

Model Context Protocol (MCP) standardises how agents discover and call tools, read resources
and fetch prompt templates - any MCP client (Claude Desktop, Cursor, LangGraph via
langchain-mcp-adapters, your own agent) can use this server without custom glue.

Run standalone (stdio):   python -m classes.class06_memory_mcp.mcp_server
Run over HTTP:            python -m classes.class06_memory_mcp.mcp_server --http   (port 8765)
"""
from __future__ import annotations

import sys
from typing import Literal

from mcp.server.fastmcp import FastMCP

from common import DATA
from classes.class05_tool_engineering import ops_tools as ops

mcp = FastMCP("ops-tools", port=8765, log_level="WARNING")

Service = Literal["checkout-api", "payments-svc", "inventory-svc", "postgres-payments",
                  "redis-cache", "batch-worker"]


# ----------------------------------------------------------------------------- tools (read-only)
@mcp.tool()
def get_metric(service: Service, metric: str) -> dict:
    """Summary of one metric for a service over the last hour: baseline, current, change point."""
    out = ops.get_metric.fn(service=service, metric=metric)
    out.pop("series", None)
    return out


@mcp.tool()
def search_logs(service: Service, level: Literal["ERROR", "WARN", "INFO"] = "ERROR",
                contains: str = "", limit: int = 5) -> dict:
    """Deduplicated recent log messages for a service, filtered by level and substring."""
    return ops.search_logs.fn(service=service, level=level, contains=contains, limit=limit)


@mcp.tool()
def get_recent_deploys(service: Service) -> dict:
    """Recent deployments for a service with change summaries, newest first."""
    return ops.get_recent_deploys.fn(service=service)

# Note: rollback_deployment is deliberately NOT exposed. Write actions stay behind the
# approval gate in the agent host - MCP servers should expose the least privilege needed.


# ----------------------------------------------------------------------------- resources
@mcp.resource("runbook://index")
def runbook_index() -> str:
    """List of available runbook ids."""
    return "\n".join(p.stem for p in sorted((DATA / "aiops" / "runbooks").glob("*.md")))


@mcp.resource("runbook://{runbook_id}")
def runbook(runbook_id: str) -> str:
    """Full text of one runbook."""
    path = DATA / "aiops" / "runbooks" / f"{runbook_id}.md"
    if not path.exists():
        raise ValueError(f"no runbook '{runbook_id}'")
    return path.read_text()


# ----------------------------------------------------------------------------- prompts
@mcp.prompt()
def incident_triage(service: str, symptom: str) -> str:
    """Standard triage prompt used by every on-call agent."""
    return (f"Incident on {service}: {symptom}.\n"
            "1) Check error rate and latency. 2) Search ERROR logs. 3) Check deploys in the last 24h. "
            "4) Name the most likely root cause with evidence. 5) Recommend a runbook. Do not execute writes.")


if __name__ == "__main__":
    mcp.run(transport="streamable-http" if "--http" in sys.argv else "stdio")

"""Class 7 - A small, framework-agnostic evaluation harness.

Concepts map 1:1 onto LangSmith / Opik:
  Dataset (examples with inputs + reference outputs) -> Target (the system under test)
  -> Evaluators (functions returning named scores) -> Experiment (results + aggregates)
  -> Comparison / regression gate between two experiments.
"""
from __future__ import annotations

import json
import re
import statistics
import time
from dataclasses import dataclass, field
from typing import Callable

from common import RUNS
from common.retrieval import tokenize

Evaluator = Callable[[dict, dict], dict[str, float]]   # (example, output) -> {metric: score}


@dataclass
class Experiment:
    name: str
    rows: list[dict] = field(default_factory=list)

    @property
    def summary(self) -> dict[str, float]:
        keys = sorted({k for r in self.rows for k in r["scores"]})
        out = {k: round(statistics.mean(r["scores"][k] for r in self.rows if k in r["scores"]), 3) for k in keys}
        lat = sorted(r["latency_ms"] for r in self.rows)
        out["p50_latency_ms"] = lat[len(lat) // 2]
        out["p95_latency_ms"] = lat[min(len(lat) - 1, int(0.95 * len(lat)))]
        return out

    def save(self) -> None:
        RUNS.mkdir(exist_ok=True)
        (RUNS / f"eval_{self.name}.json").write_text(json.dumps(
            {"name": self.name, "summary": self.summary, "rows": self.rows}, indent=1, default=str))


def run_experiment(name: str, dataset: list[dict], target: Callable[[dict], dict],
                   evaluators: list[Evaluator]) -> Experiment:
    exp = Experiment(name)
    for ex in dataset:
        t0 = time.perf_counter()
        try:
            out, err = target(ex), None
        except Exception as e:  # noqa: BLE001 - a crash is a scored failure, not a harness crash
            out, err = {}, f"{type(e).__name__}: {e}"
        latency = round((time.perf_counter() - t0) * 1000, 2)
        scores: dict[str, float] = {"no_error": 0.0 if err else 1.0}
        if not err:
            for ev in evaluators:
                scores.update(ev(ex, out))
        exp.rows.append({"input": ex, "output": out, "error": err, "scores": scores, "latency_ms": latency})
    exp.save()
    return exp


def compare(base: Experiment, cand: Experiment, tolerance: float = 0.02) -> list[str]:
    """Regression gate: list metrics where the candidate is worse than baseline beyond tolerance."""
    regressions = []
    for k, v in base.summary.items():
        if "latency" in k:
            continue
        c = cand.summary.get(k)
        if c is not None and c < v - tolerance:
            regressions.append(f"{k}: {v} -> {c}")
    return regressions


# ----------------------------------------------------------------------------- reusable evaluators
def contains_reference(ex: dict, out: dict) -> dict:
    ans = out.get("answer", "").lower()
    return {"correct": float(all(s.lower() in ans for s in ex["answer_contains"]))}


def retrieval_hit(ex: dict, out: dict) -> dict:
    return {"retrieval_hit": float(any(s.startswith(ex["relevant_doc"]) for s in out.get("source_ids", [])))}


def citation_valid(ex: dict, out: dict) -> dict:
    cited = set(re.findall(r"\[([\w\-]+#\d+)\]", out.get("answer", "")))
    ok = bool(cited) and cited <= set(out.get("source_ids", []))
    return {"citations_valid": float(ok)}


def groundedness(ex: dict, out: dict) -> dict:
    """Share of answer sentences whose content words mostly appear in the retrieved context.
    A cheap proxy; Class 8 replaces it with an LLM judge."""
    ctx = set(tokenize(out.get("context", "")))
    sents = [s for s in re.split(r"(?<=[.!?])\s+", re.sub(r"\[[^\]]+\]", "", out.get("answer", ""))) if len(s) > 10]
    if not sents:
        return {"grounded": 0.0}
    ok = sum(len(set(tokenize(s)) & ctx) / max(1, len(set(tokenize(s)))) >= 0.6 for s in sents)
    return {"grounded": ok / len(sents)}


def trajectory_match(expected_tools: list[str], forbidden: list[str] | None = None) -> Evaluator:
    """Agent evaluator: did it call the required tools in order, avoid forbidden ones, stay efficient?"""
    def ev(ex: dict, out: dict) -> dict:
        calls = [c for c in out.get("tool_calls", [])]
        it = iter(calls)
        in_order = all(any(t == c for c in it) for t in expected_tools)
        return {"required_tools_in_order": float(in_order),
                "no_forbidden_tools": float(not set(forbidden or []) & set(calls)),
                "step_efficiency": min(1.0, len(expected_tools) / max(1, len(calls)))}
    return ev


def as_table(exps: list[Experiment]) -> str:
    keys = list(dict.fromkeys(k for e in exps for k in e.summary))
    lines = [f"{'metric':<26}" + "".join(f"{e.name:>18}" for e in exps)]
    for k in keys:
        lines.append(f"{k:<26}" + "".join(f"{e.summary.get(k, '-'):>18}" for e in exps))
    return "\n".join(lines)

"""Class 7 - Running the same evaluation on LangSmith and Opik.

Both platforms give you hosted datasets, experiment comparison UIs, trace-linked results and
human annotation queues. The concepts are identical to eval_harness.py.

LangSmith:  pip install langsmith   export LANGSMITH_API_KEY=... LANGSMITH_TRACING=true
Opik:       pip install opik        export OPIK_API_KEY=...  (or `opik configure` for self-hosted)

Run:  python -m classes.class07_evaluation.vendor_integrations langsmith|opik
"""
from __future__ import annotations

import os
import sys

from common.domain import load_clinical_golden

from .example import CHUNKS, rag_target
from common.retrieval import HybridRetriever


def target_fn():
    hybrid = HybridRetriever(CHUNKS)
    return rag_target(lambda q, k: hybrid.search(q, k), 3)


def run_langsmith() -> None:
    from langsmith import Client, evaluate

    client = Client()
    name = "clinical-policy-qa"
    if not client.has_dataset(dataset_name=name):
        ds = client.create_dataset(name, description="Synthetic clinical policy golden set")
        client.create_examples(dataset_id=ds.id,
                               inputs=[{"q": g["q"]} for g in load_clinical_golden()],
                               outputs=[{"answer_contains": g["answer_contains"],
                                         "relevant_doc": g["relevant_doc"]} for g in load_clinical_golden()])
    t = target_fn()

    def correct(outputs: dict, reference_outputs: dict) -> bool:
        return all(s.lower() in outputs["answer"].lower() for s in reference_outputs["answer_contains"])

    def retrieval_hit(outputs: dict, reference_outputs: dict) -> bool:
        return any(s.startswith(reference_outputs["relevant_doc"]) for s in outputs["source_ids"])

    evaluate(lambda inputs: t({"q": inputs["q"]}), data=name,
             evaluators=[correct, retrieval_hit], experiment_prefix="hybrid-k3")


def run_opik() -> None:
    import opik
    from opik.evaluation import evaluate
    from opik.evaluation.metrics import Contains, base_metric, score_result

    client = opik.Opik()
    ds = client.get_or_create_dataset("clinical-policy-qa")
    ds.insert([{"q": g["q"], "reference": g["answer_contains"][0], "relevant_doc": g["relevant_doc"]}
               for g in load_clinical_golden()])
    t = target_fn()

    class RetrievalHit(base_metric.BaseMetric):
        def score(self, source_ids, relevant_doc, **_):
            return score_result.ScoreResult(name="retrieval_hit",
                                            value=float(any(s.startswith(relevant_doc) for s in source_ids)))

    def task(item: dict) -> dict:
        out = t({"q": item["q"]})
        return {"output": out["answer"], "source_ids": out["source_ids"], "reference": item["reference"],
                "relevant_doc": item["relevant_doc"]}

    evaluate(dataset=ds, task=task, scoring_metrics=[Contains(case_sensitive=False), RetrievalHit()],
             experiment_name="hybrid-k3")


if __name__ == "__main__":
    which = (sys.argv[1:] or ["langsmith"])[0]
    need = {"langsmith": "LANGSMITH_API_KEY", "opik": "OPIK_API_KEY"}[which]
    if not os.getenv(need):
        print(f"Set {need} to push this experiment to {which}. The offline harness is in example.py.")
        sys.exit(0)
    run_langsmith() if which == "langsmith" else run_opik()

"""Class 9 - Agentic RAG for clinical policy questions (LangGraph).

Plain RAG retrieves once and hopes. Agentic RAG lets the system reason about retrieval:

  route -> plan (decompose multi-part questions) -> retrieve -> grade documents
        -> (weak evidence? rewrite query and retry, max 2) -> generate -> check grounding
        -> (ungrounded? escalate) -> answer | escalate to human

This combines ideas from Self-RAG, Corrective RAG (CRAG) and query decomposition.

Run:  python -m classes.class09_agentic_rag_finetuning.agentic_rag
"""
from __future__ import annotations

import operator
import re
from typing import Annotated, Literal, TypedDict

from langgraph.graph import END, START, StateGraph

from common import DATA
from common.guardrails import check_citations
from common.llm import get_llm
from common.retrieval import (Chunk, HybridRetriever, chunk_markdown, extractive_answer,
                              format_context, load_markdown_dir, tokenize)
from common.tracing import traced

RETRIEVER = HybridRetriever([c for d, t in load_markdown_dir(DATA / "clinical" / "guidelines")
                             for c in chunk_markdown(d, t, 700)])

# brand names and colloquialisms -> policy vocabulary (an LLM does this online)
SYNONYMS = {"a1c": "HbA1c", "sleep test": "home sleep apnea testing", "back mri": "MRI lumbar spine",
            "knee scope": "knee arthroscopy meniscectomy", "ozempic": "semaglutide",
            "mounjaro": "tirzepatide", "pt": "physical therapy"}
STOP = {"what", "is", "the", "a", "an", "for", "of", "to", "and", "or", "in", "on", "which", "when", "how",
        "does", "do", "be", "with", "any", "should", "must", "before", "long", "used", "needed", "starting"}


def content(q: str) -> set[str]:
    return {t for t in tokenize(q) if len(t) > 1} - STOP


OUT_OF_SCOPE = ["dose", "dosage", "should i take", "diagnose", "weather", "stock price"]


class RAGState(TypedDict):
    question: str
    route: str
    sub_questions: list[str]
    queries: list[str]
    attempts: int
    docs: list[tuple[Chunk, float]]
    relevant: list[tuple[Chunk, float]]
    answer: str
    grounded: bool
    log: Annotated[list[str], operator.add]


# ----------------------------------------------------------------------------- nodes
@traced("route")
def route(s: RAGState) -> dict:
    q = s["question"].lower()
    r = "refuse" if any(w in q for w in OUT_OF_SCOPE) else "policy_qa"
    r = get_llm().chat(f"Classify as policy_qa or refuse (clinical advice / off-topic): {s['question']}",
                       fallback=lambda: r).strip().lower()
    return {"route": "refuse" if "refuse" in r else "policy_qa", "log": [f"route={r}"]}


def plan(s: RAGState) -> dict:
    q = s["question"]
    m = re.match(r"(?i)compare (.+?) for (.+?) and (.+?)[?.]?$", q)
    subs = [f"{m.group(1)} for {m.group(2)}", f"{m.group(1)} for {m.group(3)}"] if m else [q]
    return {"sub_questions": subs, "queries": subs, "log": [f"plan: {subs}"]}


def retrieve(s: RAGState) -> dict:
    docs, seen = [], set()
    for q in s["queries"]:
        for c, sc in RETRIEVER.search(q, k=3):
            if c.id not in seen:
                seen.add(c.id)
                docs.append((c, sc))
    return {"docs": docs, "attempts": s["attempts"] + 1,
            "log": [f"retrieve#{s['attempts'] + 1}: {[c.id for c, _ in docs]}"]}


def grade(s: RAGState) -> dict:
    """Keep only chunks that are relevant to at least one sub-question (LLM yes/no, offline overlap)."""
    keep = []
    for c, sc in s["docs"]:
        def offline():  # share of the query's content words found in the chunk
            ctoks = set(tokenize(c.text))
            best = max(len(content(q) & ctoks) / max(1, len(content(q))) for q in s["queries"])
            return "yes" if best >= 0.25 else "no"
        v = get_llm().chat(f"Is this passage relevant to any of {s['queries']}? yes/no\n\n{c.text}", fallback=offline)
        if v.strip().lower().startswith("y"):
            keep.append((c, sc))
    return {"relevant": keep, "log": [f"grade: kept {len(keep)}/{len(s['docs'])}"]}


def rewrite(s: RAGState) -> dict:
    def offline():
        out = []
        for q in s["queries"]:
            ql = q.lower()
            for k, v in SYNONYMS.items():
                q = re.sub(rf"(?i)\b{re.escape(k)}\b", v, q)
            out.append(q)
        return "\n".join(out)
    new = get_llm().chat("Rewrite each query for a medical-policy search engine using formal terms, one per line:\n"
                         + "\n".join(s["queries"]), fallback=offline).splitlines()
    return {"queries": [q for q in new if q.strip()], "log": [f"rewrite: {new}"]}


def generate(s: RAGState) -> dict:
    ctx = format_context(s["relevant"])
    subs = s["sub_questions"]
    prompt = (f"Answer using ONLY the context; cite [chunk-id] after each sentence. Sub-questions: {subs}\n\n"
              f"{ctx}\n\nQuestion: {s['question']}")

    def fb():  # offline: best supporting sentence per sub-question, no duplicates
        parts, used = [], set()
        for q in (s["queries"] if len(s["queries"]) == len(subs) else subs):
            cands = extractive_answer(q, s["relevant"], n=3)
            for piece in re.findall(r"[^\]]+?\[[^\]]+\]", cands):
                if piece.strip() not in used:
                    used.add(piece.strip())
                    parts.append(piece.strip())
                    break
        return " ".join(parts)
    return {"answer": get_llm().chat(prompt, fallback=fb), "log": ["generate"]}


def check(s: RAGState) -> dict:
    g = check_citations(s["answer"], {c.id for c, _ in s["relevant"]})
    return {"grounded": g.allowed, "log": [f"grounding: {'ok' if g.allowed else g.findings}"]}


def refuse(s: RAGState) -> dict:
    return {"answer": "I can only answer questions about coverage policy criteria. For clinical or dosing "
                      "decisions, please consult the treating clinician.", "grounded": True, "log": ["refused"]}


def escalate(s: RAGState) -> dict:
    return {"answer": "Not enough policy evidence to answer confidently - routed to a human reviewer.",
            "log": ["escalated"]}


# ----------------------------------------------------------------------------- edges
def after_grade(s: RAGState) -> Literal["generate", "rewrite", "escalate"]:
    if len(s["relevant"]) >= len(s["sub_questions"]):
        return "generate"
    return "rewrite" if s["attempts"] < 2 else ("generate" if s["relevant"] else "escalate")


def build():
    g = StateGraph(RAGState)
    for name, fn in [("route", route), ("plan", plan), ("retrieve", retrieve), ("grade", grade),
                     ("rewrite", rewrite), ("generate", generate), ("check", check),
                     ("refuse", refuse), ("escalate", escalate)]:
        g.add_node(name, fn)
    g.add_edge(START, "route")
    g.add_conditional_edges("route", lambda s: "refuse" if s["route"] == "refuse" else "plan")
    g.add_edge("plan", "retrieve")
    g.add_edge("retrieve", "grade")
    g.add_conditional_edges("grade", after_grade)
    g.add_edge("rewrite", "retrieve")
    g.add_edge("generate", "check")
    g.add_conditional_edges("check", lambda s: END if s["grounded"] else "escalate")
    g.add_edge("refuse", END)
    g.add_edge("escalate", END)
    return g.compile()


def ask(app, q: str) -> dict:
    return app.invoke({"question": q, "route": "", "sub_questions": [], "queries": [], "attempts": 0,
                       "docs": [], "relevant": [], "answer": "", "grounded": False, "log": []})


if __name__ == "__main__":
    app = build()
    for q in ["What a1c is needed before starting ozempic?",
              "Compare the conservative therapy requirement for lumbar MRI and knee arthroscopy.",
              "What dose of semaglutide should I take?"]:
        out = ask(app, q)
        print(f"\nQ: {q}")
        for line in out["log"]:
            print(f"   · {line}")
        print(f"A: {out['answer']}")

